// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 first, uint256 second) internal {
        try c.SetMinSum(first) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool reverted;
        try c.SetMinSum(second) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && c.MinSum() == first);
    }

    function testFuzz_run(uint256 first, uint256 second) public {
        _run(first, second);
    }

    receive() external payable {}
}
